# Analyze all standard peg-solitaire branches for the current five-peg layout.
from functools import lru_cache
pegs={(7,1),(6,2),(7,2),(4,3),(6,3)}
@lru_cache(None)
def moves(ps):
    ps=set(ps)
    out=[]
    for x,y in ps:
        for dx,dy in [(2,0),(-2,0),(0,2),(0,-2)]:
            mid=(x+dx//2,y+dy//2); dst=(x+dx,y+dy)
            if mid in ps and dst not in ps and 0<=dst[0]<=7 and 1<=dst[1]<=6:
                out.append(((x,y),dst,tuple(sorted((ps-{(x,y),mid})|{dst}))))
    return out
def search(ps,path=()):
    if len(ps)==1:return path
    for a,b,nxt in moves(tuple(sorted(ps))):
        z=search(set(nxt),path+((a,b),))
        if z:return z
print('solution',search(pegs))
print('first moves',[(a,b) for a,b,_ in moves(tuple(sorted(pegs)))])
